// Mirror of src/matcher.js. Edit BRANDS + CONFIG to make it yours.
const BRANDS = {
  "JS": { aliases: ["js industries", "jason stevenson"], strict: ["js"] },
  "DHD": { aliases: ["darren handley designs", "darren handley"], strict: ["dhd"] },
  "Pyzel": { aliases: ["pyzel"], strict: [] },
  "Channel Islands": { aliases: ["channel islands", "channel island", "al merrick"], strict: ["ci"] },
  "Haydenshapes": { aliases: ["haydenshapes", "hayden shapes"], strict: ["hs", "hayden"] },
};
const CONFIG = {
  brands: ["JS", "DHD", "Pyzel", "Channel Islands", "Haydenshapes"],
  minLengthIn: 68, maxLengthIn: 78, minVolumeL: 30, maxPrice: 900,
  regionPattern: /perth|\bwa\b|western australia/,
  centre: { lat: -31.9505, lon: 115.8605 }, radiusKm: 30,
};
const EXCLUDE_TITLE = ["surfboard bag","board bag","board cover","surfboard sock","fins only","fin set","surfboard fin"," fins","kitesurf","kiteboard","wakeboard","skimboard","bodyboard","boogie board","sup ","paddle board","wetsuit","leash only"," rack","traction pad","deck grip"];
function norm(s){return (s||"").toString().toLowerCase().replace(/[‘’ʼ′]/g,"'").replace(/[“”ʺ″]/g,'"').replace(/\s+/g," ").trim();}
function escapeRe(s){return s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");}
function matchBrand(t){for(const b of CONFIG.brands){const d=BRANDS[b];if(!d)continue;for(const a of d.aliases)if(t.includes(a))return{brand:b,alias:a,strict:false};for(const a of d.strict)if(new RegExp("\\b"+escapeRe(a)+"\\b").test(t))return{brand:b,alias:a,strict:true};}return null;}
function parseLengthIn(t){const re=/\b([4-9])\s*(?:['"]|ft|feet)\s*(\d{1,2})?/g;let m;while((m=re.exec(t))){const ft=parseInt(m[1],10);const inch=m[2]!==undefined?parseInt(m[2],10):0;if(inch>11)continue;return ft*12+inch;}return null;}
function parseVolumeL(t){const re=/(\d{2}(?:\.\d)?)\s*(?:l\b|lt\b|litres?\b|liters?\b)/g;let m;while((m=re.exec(t))){const v=parseFloat(m[1]);if(v>=15&&v<=70)return v;}return null;}
function haversineKm(a,b){const R=6371,r=d=>d*Math.PI/180;const dLat=r(b.lat-a.lat),dLon=r(b.lon-a.lon);const s=Math.sin(dLat/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(s));}
function getTitle(l){return l.marketplace_listing_title||l.listingTitle||l.title||"";}
function getPrice(l){const lp=l.listing_price||l.listingPrice||{};if(lp.amount!=null&&!isNaN(parseFloat(lp.amount)))return Math.round(parseFloat(lp.amount));const f=lp.formatted_amount_zeros_stripped||lp.formatted_amount||l.price||"";const d=(""+f).replace(/[^\d]/g,"");return d?parseInt(d,10):null;}
function getLoc(l){const rg=(l.location&&l.location.reverse_geocode)||{};const text=(rg.city_page&&rg.city_page.display_name)||[rg.city,rg.state].filter(Boolean).join(", ")||(l.locationText&&l.locationText.text)||null;const lat=l.location&&(l.location.latitude??l.location.lat);const lon=l.location&&(l.location.longitude??l.location.lon);return{text,lat:typeof lat==="number"?lat:null,lon:typeof lon==="number"?lon:null};}
function getPhoto(l){return (l.primary_listing_photo&&l.primary_listing_photo.photo_image_url)||(l.listingPhotos&&l.listingPhotos[0]&&l.listingPhotos[0].image&&l.listingPhotos[0].image.uri)||null;}
function getUrl(l){return l.listingUrl||l.itemUrl||(l.id?("https://www.facebook.com/marketplace/item/"+l.id):null);}
function regionCheck(loc){if(loc.lat!=null&&loc.lon!=null&&CONFIG.centre&&CONFIG.radiusKm){const km=Math.round(haversineKm(CONFIG.centre,{lat:loc.lat,lon:loc.lon}));return{ok:km<=CONFIG.radiusKm,km};}if(CONFIG.regionPattern)return{ok:CONFIG.regionPattern.test(norm(loc.text||"")),km:null};return{ok:true,km:null};}
function matchListing(l){const title=norm(getTitle(l));if(l.is_sold===true||l.isSold===true)return{isMatch:false};if(!title)return{isMatch:false};if(EXCLUDE_TITLE.some(k=>title.includes(k)))return{isMatch:false};const brand=matchBrand(title);if(!brand)return{isMatch:false};const unknowns=[];const price=getPrice(l);if(price==null)unknowns.push("price");else if(price>CONFIG.maxPrice)return{isMatch:false};const length_in=parseLengthIn(title);if(length_in==null)unknowns.push("length");else if(length_in<CONFIG.minLengthIn||length_in>CONFIG.maxLengthIn)return{isMatch:false};const volume_l=parseVolumeL(title);if(volume_l==null)unknowns.push("volume");else if(volume_l<CONFIG.minVolumeL)return{isMatch:false};const loc=getLoc(l);const region=regionCheck(loc);if(!region.ok)return{isMatch:false};const confidence=(brand.strict||unknowns.length)?"review":"high";return{isMatch:true,confidence,brand:brand.brand,brandAlias:brand.alias,price,length_in,volume_l,distance_km:region.km,region:loc.text,unknowns};}
const listings=$input.all().map(i=>i.json);const out=[];
for(const l of listings){const r=matchListing(l);if(!r.isMatch)continue;out.push({json:{listing_id:String(l.id??getUrl(l)),title:getTitle(l)||null,price:r.price,url:getUrl(l),image_url:getPhoto(l),brand:r.brand,brand_alias:r.brandAlias,length_in:r.length_in,volume_l:r.volume_l,distance_km:r.distance_km,region:r.region,confidence:r.confidence,unknowns:r.unknowns}});}
return out;

// Mirror of src/caption.js.
const j=$json;
function ftin(inch){if(inch==null)return null;const f=Math.floor(inch/12),i=inch%12;return `${f}'${i}"`;}
const CURRENCY="A$";
const len=j.length_in!=null?ftin(j.length_in):"length n/a";
const vol=j.volume_l!=null?`${j.volume_l}L`:"vol n/a";
const price=j.price!=null?`${CURRENCY}${j.price}`:"price n/a";
const dist=j.distance_km!=null?`${j.distance_km}km away`:(j.region||"");
const flag=j.confidence==="review"?"\n⚠️ dims unconfirmed, check the photo":"";
const caption=`🏄 NEW ${j.brand} — ${price}\n${j.title||""}\n📏 ${len} · ${vol} · 📍 ${dist}${flag}\n\n💬 \"Hey mate, is this still available? Keen to come have a look 👀\"\n\n<a href=\"${j.url}\">Open listing ↗</a>`;
return { json: { ...j, caption } };
